  "enabledPlugins": {
    "core@skillshed": true,
    "matt@skillshed": false
  },
  "extraKnownMarketplaces": {
    "skillshed": {
      "source": {
        "source": "github",
        "repo": "farmhutsoftwareteam/skillshed"
      }
    }
  }
}
